using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SaucyMVC.Data; using SaucyMVC.Models; using SaucyMVC.ViewModels;
namespace SaucyMVC.Controllers;
public class AccountController:Controller {
 readonly SaucyDbContext _db; readonly PasswordHasher<User> _hasher=new(); public AccountController(SaucyDbContext db)=>_db=db;
 [HttpGet] public IActionResult Login(string? role=null,string? returnUrl=null){ViewBag.Role=role;ViewBag.ReturnUrl=returnUrl;return View(new LoginViewModel());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginViewModel m,string? role=null,string? returnUrl=null){ViewBag.Role=role;ViewBag.ReturnUrl=returnUrl;if(!ModelState.IsValid)return View(m);var email=m.Email.Trim().ToLowerInvariant();var u=await _db.Users.SingleOrDefaultAsync(x=>x.Email==email&&x.IsActive);if(u==null||_hasher.VerifyHashedPassword(u,u.PasswordHash,m.Password)==PasswordVerificationResult.Failed){ModelState.AddModelError("","Invalid email or password.");return View(m);} if(!string.IsNullOrWhiteSpace(role)&&!u.Role.Equals(role,StringComparison.OrdinalIgnoreCase)){ModelState.AddModelError("",$"This account is not a {role} account.");return View(m);} u.LastLoginAt=DateTime.Now;await _db.SaveChangesAsync();HttpContext.Session.SetInt32("UserId",u.Id);HttpContext.Session.SetString("FullName",u.FullName);HttpContext.Session.SetString("Role",u.Role);if(u.Role=="Customer"&&Url.IsLocalUrl(returnUrl))return LocalRedirect(returnUrl!);return u.Role switch{"Admin"=>RedirectToAction("Index","Admin"),"Staff"=>RedirectToAction("Index","Staff"),_=>RedirectToAction("Index","Home")};}
 [HttpGet] public IActionResult Register(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View(new RegisterViewModel());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Register(RegisterViewModel m,string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;var email=m.Email.Trim().ToLowerInvariant();if(await _db.Users.AnyAsync(x=>x.Email==email))ModelState.AddModelError(nameof(m.Email),"That email is already registered.");if(!ModelState.IsValid)return View(m);var u=new User{FullName=m.FullName.Trim(),Email=email,PhoneNumber=m.PhoneNumber.Trim(),Role="Customer"};u.PasswordHash=_hasher.HashPassword(u,m.Password);_db.Users.Add(u);await _db.SaveChangesAsync();TempData["Success"]="Account created. You can now sign in.";return RedirectToAction(nameof(Login),new{returnUrl});}
 [HttpPost,ValidateAntiForgeryToken] public IActionResult Logout(){HttpContext.Session.Clear();return RedirectToAction("Index","Home");}
}
